import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Map;
import java.util.HashMap;
import java.util.Collections;

public class CommentsConfigurationTest {

    @Test
    public void constructor_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        assertNull(config.comments);
    }

    @Test
    public void constructor_withComments_test() {
        Map<String, List<String>> commentsMap = new HashMap<>();
        String comment1 = "Comment 1";
        String comment2 = "Comment 2";
        CommentsConfiguration config = new CommentsConfiguration(commentsMap);
        assertEquals(1, config.comments.size());
        assertTrue(config.comments.containsKey(comment1));
    }

    @Test
    public void setComment_emptyPath_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("", "", "New comment");
        assertNull(config.comments.get(""));
    }

    @Test
    public void setComment_singleLineComment_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("path", "\n");
        assertTrue(config.comments.containsKey("path"));
        assertEquals(0, ((List<String>) config.comments.get("path")).size());
    }

    @Test
    public void setComment_multipleLinesComment_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        String comment1 = "Comment 1";
        String comment2 = "Comment 2";
        config.setComment("path", comment1, comment2);
        assertTrue(config.comments.containsKey("path"));
        assertEquals(2, ((List<String>) config.comments.get("path")).size());
    }

    @Test
    public void setComment_duplicatePath_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        String comment1 = "Comment 1";
        String comment2 = "Comment 2";
        config.setComment("path", comment1, comment2);
        config.setComment("path", "", "");
        assertEquals(1, config.comments.size());
    }

    @Test
    public void getAllComments_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        Map<String, List<String>> commentsMap = new HashMap<>();
        String comment1 = "Comment 1";
        String comment2 = "Comment 2";
        commentsMap.put("path", Arrays.asList(comment1, comment2));
        config.comments = commentsMap;
        assertEquals(1, ((List<String>) config.getAllComments().get("path")).size());
    }

    @Test
    public void getAllComments_emptyTest() {
        CommentsConfiguration config = new CommentsConfiguration();
        assertTrue(config.getAllComments().isEmpty());
    }
}
